        'moon.faq.q6': 'متى يبدأ الشهر الهجريّ القادم؟',
        'moon.faq.a6': 'يبدأ الشهر الهجريّ القادم برؤية هلاله بعد غروب شمس اليوم الـ29 من الشهر الحاليّ. قد يختلف التاريخ بيوم حسب الرؤية المحلّيّة للهلال.',
        'moon.faq.q7': 'متى رمضان القادم؟',
        'moon.faq.a7': 'يبدأ شهر رمضان برؤية هلاله في اليوم الـ29 من شعبان. التاريخ النهائيّ يعتمد على الرؤية المحلّيّة للهلال في كلّ بلد.',
        'moon.faq.q8': 'متى عيد الفطر القادم؟',
        'moon.faq.a8': 'يبدأ عيد الفطر بظهور هلال شهر شوّال في اليوم الـ29 من رمضان. يُحتفَل به أوّل شوّال ويستمرّ ثلاثة أيّام.',
        'moon.faq.q9': 'متى عيد الأضحى القادم؟',
        'moon.faq.a9': 'يقع عيد الأضحى في اليوم العاشر من ذي الحجّة، بعد رؤية هلاله في اليوم الـ29 من ذي القعدة. يُحتفَل به أربعة أيّام.',
        'moon.faq.q10': 'كيف أرى الهلال بالعين المجرّدة؟',
        'moon.faq.a10': 'يُرى الهلال بعد غروب الشمس في الأفق الغربيّ، عند عمر قمر لا يقلّ عن 15 ساعة تقريباً. يحتاج أفقاً غربيّاً صافياً بلا غيوم.',
        'moon.faq.q11': 'ما هي أطوار القمر الثمانية؟',
        'moon.faq.a11': 'أطوار القمر الثمانية: (1) المحاق، (2) الهلال المتزايد، (3) التربيع الأوّل، (4) الأحدب المتزايد، (5) البدر، (6) الأحدب المتناقص، (7) التربيع الأخير، (8) الهلال المتناقص. تتكرّر كلّ 29.5 يوم.',
        'moon.faq.q12': 'لماذا تختلف مواعيد مطلع القمر من مدينة لأخرى؟',
        'moon.faq.a12': 'مطلع القمر يعتمد على خطّ الطول الجغرافيّ للمدينة. الفرق قد يصل إلى 12 ساعة بين شرق العالم وغربه. خطّ العرض يؤثّر قليلاً على الاتّجاه.',
        'moon.faq.q13': 'ما هي ليلة القدر؟',
        'moon.faq.a13': 'ليلة القدر ليلة مباركة في العشر الأواخر من رمضان، يُرجَّح أنّها ليلة 27 لكنّها قد تكون في أيّ من الليالي الوتريّة (21، 23، 25، 27، 29).',
        'moon.faq.q14': 'هل يمكن رؤية القمر في النهار؟',
        'moon.faq.a14': 'نعم، يمكن رؤية القمر أحياناً في النهار، خاصّة خلال أطوار التربيع الأوّل والتربيع الأخير والأحدب. في طور البدر يُرى ليلاً فقط.',
        // ===== FAQ Live (ديناميكيّ: يُملأ JS بأرقام وتواريخ حقيقيّة) =====
        'moon.faq_live_title': '🔴 الآن: القمر الليلة',
        'moon.faq_general_title': '❓ أسئلة عامّة عن القمر',
        'moon.faq.dq1': 'ما طور القمر الليلة في مدينتك؟',
        'moon.faq.da1': 'يعرض الموقع طور القمر الحاليّ ونسبة إضاءته لحظياً. يمرّ القمر بثمانية أطوار خلال 29.5 يوم.',
        'moon.faq.dq2': 'متى البدر القادم؟',
        'moon.faq.da2': 'البدر يتكرّر كلّ 29.5 يوم. يعرض الموقع التاريخ الميلاديّ والهجريّ للبدر القادم مع نسبة إضاءة 100٪.',
        'moon.faq.dq3': 'متى المحاق القادم؟',
        'moon.faq.da3': 'المحاق هو اللحظة التي يكون فيها القمر بين الأرض والشمس بإضاءة 0٪. يتكرّر كلّ 29.5 يوم ويبدأ به الشهر القمريّ الجديد.',
        'moon.faq.dq4': 'كم يومًا حتّى البدر القادم؟',
        'moon.faq.da4': 'يحسب الموقع عدد الأيّام المتبقّية حتّى البدر التالي تلقائيًّا بناءً على الموقع الفلكيّ الحاليّ للقمر.',
        'moon.faq.dq5': 'كم عمر القمر اليوم؟',
        'moon.faq.da5': 'عمر القمر هو عدد الأيّام المنقضية منذ آخر محاق، ويتراوح بين 0 و29.5 يوم.',
        'moon.faq.dq6': 'متى يطلع القمر الليلة في مدينتك؟',
        'moon.faq.da6': 'مطلع القمر يعتمد على خطّ الطول الجغرافيّ لموقعك. يعرض الموقع وقت المطلع بالتوقيت المحلّيّ بعد تحديد الموقع.',
        'moon.faq.dq7': 'متى يغيب القمر الليلة في مدينتك؟',
        'moon.faq.da7': 'مغيب القمر يعتمد على خطّ الطول الجغرافيّ وخطّ العرض لموقعك. يعرض الموقع وقت المغيب بالتوقيت المحلّيّ.',
        'moon.faq.dq8': 'ما المسافة بين مدينتك والقمر الآن؟',
        'moon.faq.da8': 'تتراوح المسافة بين الأرض والقمر بين 356,500 كم (الحضيض) و406,700 كم (الأوج). يحسب الموقع المسافة الدقيقة من مدينتك إلى القمر.',
        // ===== FAQ General (أسئلة عامّة جديدة) =====
        'moon.faq.q15': 'ما خسوف القمر ولماذا يحدث؟',
        'moon.faq.a15': 'خسوف القمر يحدث عندما تقع الأرض بين الشمس والقمر فيدخل القمر ظلّ الأرض. يحدث فقط في طور البدر، ويتراوح بين خسوف جزئيّ وخسوف كلّيّ. في الخسوف الكلّيّ يظهر القمر بلون أحمر داكن يُعرف بـ«القمر الدمويّ» بسبب تشتّت ضوء الشمس في غلاف الأرض الجوّيّ.',
        'moon.faq.q16': 'لماذا نرى دائمًا نفس وجه القمر؟',
        'moon.faq.a16': 'يُعرف هذا بـ«القفل المدّيّ» (tidal locking): دورة القمر حول نفسه (27.3 يوم) تساوي دورته حول الأرض. لذلك يظلّ أحد وجهيه مواجهاً للأرض دائماً، والوجه الآخر يُعرف بـ«الجانب البعيد» وقد صُوِّر لأوّل مرّة عام 1959 بمركبة لونا 3.',
        'moon.faq.q17': 'كيف يؤثّر القمر على المدّ والجزر؟',
        'moon.faq.a17': 'جاذبيّة القمر تسحب مياه المحيطات فتنتفخ تجاه القمر (مدّ) وفي الجانب المقابل أيضاً. بين النتوءين يحدث الجزر. يحدث مدّان وجزران في اليوم الواحد تقريباً. عند اجتماع القمر مع الشمس (محاق أو بدر) يصل المدّ لأقصاه ويُسمّى «مدّ الربيع».',
        'moon.faq.q18': 'هل تؤثّر أطوار القمر على النوم والمزاج؟',
        'moon.faq.a18': 'دراسات علميّة محدودة أظهرت أنّ بعض الأشخاص يعانون من نوم أقلّ جودة بنحو 20-30 دقيقة في ليالي البدر، وقد يعود ذلك إلى زيادة الضوء. لكن التأثير طفيف ويختلف من شخص لآخر، ولا يوجد دليل علميّ قاطع على تأثيره على المزاج.',
        'moon.faq.q19': 'لماذا يبدو القمر أحيانًا أصفر أو أحمر؟',
        'moon.faq.a19': 'عندما يكون القمر قريباً من الأفق، ضوؤه يمرّ بطبقة أسمك من الغلاف الجوّيّ، فيتشتّت الضوء الأزرق ويبقى الأحمر والأصفر. نفس الظاهرة تُسبّب شروقاً وغروباً ملوّنَين للشمس.',
        'moon.faq.q20': 'ما معنى «القمر الأزرق» و«القمر العملاق»؟',
        'moon.faq.a20': '«القمر الأزرق» (Blue Moon): بدر ثانٍ في الشهر الميلاديّ نفسه، يحدث كلّ 2.7 سنة تقريباً. «القمر العملاق» (Supermoon): بدر يتزامن مع أقرب نقطة للقمر من الأرض، فيظهر أكبر بـ14٪ وأكثر إشراقاً بـ30٪.',
