        'moon.fc_rise': 'Moonrise',
        'moon.fc_set': 'Moonset',
        'moon.fc_hijri': '🌙 Hijri Date',
        'moon.fc_details_cta': 'Details',
        'moon.cities_title': '🌐 Moon Tonight in Other Cities',
        'moon.faq_title': '❓ Frequently Asked Questions about the Moon',
        'moon.faq.q1': 'What is the moon phase tonight?',
        'moon.faq.a1': 'This site shows the current moon phase and illumination percentage live, based on your location and local time. The moon cycles through eight phases over 29.5 days.',
        'moon.faq.q2': 'When is the next full moon?',
        'moon.faq.a2': 'A full moon occurs every 29.5 days. The site displays the Gregorian and Hijri date of the next full moon, at 100% illumination.',
        'moon.faq.q3': 'What time does the moon rise tonight?',
        'moon.faq.a3': 'Moonrise depends on your longitude. After your location is determined, the site shows moonrise and moonset times in your local timezone.',
        'moon.faq.q4': 'How is moon illumination calculated?',
        'moon.faq.a4': 'Moon illumination is the portion of the lunar surface lit by the sun as seen from Earth. It ranges from 0% (new moon) to 100% (full moon), calculated astronomically from the Sun–Moon–Earth angle.',
        'moon.faq.q5': 'What is the difference between a new moon and a crescent?',
        'moon.faq.a5': "A new moon is the instant the Moon lies between Earth and Sun (0% illumination, invisible). A crescent appears one or two days after the new moon, as the first thin bow of light in the sky.",
        'moon.faq.q6': 'When does the next Islamic (Hijri) month begin?',
        'moon.faq.a6': "The next Hijri month begins with the sighting of its crescent after sunset on the 29th of the current month. The date may vary by one day depending on local crescent visibility.",
        'moon.faq.q7': 'When is the next Ramadan?',
        'moon.faq.a7': 'Ramadan begins with the sighting of its crescent on the 29th of Shaban. The exact date depends on local crescent observation in each country.',
        'moon.faq.q8': 'When is the next Eid al-Fitr?',
        'moon.faq.a8': 'Eid al-Fitr begins with the sighting of the Shawwal crescent on the 29th of Ramadan. It is celebrated on the 1st of Shawwal and lasts three days.',
        'moon.faq.q9': 'When is the next Eid al-Adha?',
        'moon.faq.a9': 'Eid al-Adha falls on the 10th of Dhu al-Hijjah, after the crescent of that month is sighted on the 29th of Dhu al-Qidah. It is celebrated for four days.',
        'moon.faq.q10': 'How can I see the crescent with the naked eye?',
        'moon.faq.a10': 'The crescent is visible after sunset on the western horizon when the Moon is at least about 15 hours old. A clear, cloudless western horizon is required.',
        'moon.faq.q11': 'What are the eight phases of the moon?',
        'moon.faq.a11': 'The eight lunar phases are: (1) New Moon, (2) Waxing Crescent, (3) First Quarter, (4) Waxing Gibbous, (5) Full Moon, (6) Waning Gibbous, (7) Last Quarter, (8) Waning Crescent. The cycle repeats every 29.5 days.',
        'moon.faq.q12': 'Why do moonrise times differ between cities?',
        'moon.faq.a12': 'Moonrise depends on a city\u2019s longitude. The difference can reach up to 12 hours between the easternmost and westernmost parts of the world. Latitude has a minor effect on direction.',
        'moon.faq.q13': 'What is Laylat al-Qadr (the Night of Power)?',
        'moon.faq.a13': 'Laylat al-Qadr is a blessed night in the last ten nights of Ramadan, most likely the 27th but possibly any of the odd nights (21, 23, 25, 27, 29).',
        'moon.faq.q14': 'Can the moon be seen during the day?',
        'moon.faq.a14': 'Yes, the moon can sometimes be seen in daytime, especially during the First Quarter, Last Quarter, and gibbous phases. During the full moon it is seen only at night.',
        // ===== FAQ Live (dynamic: filled by JS with real numbers & dates) =====
        'moon.faq_live_title': '🔴 Right Now: The Moon Tonight',
        'moon.faq_general_title': '❓ General Questions about the Moon',
        'moon.faq.dq1': "What is tonight's moon phase in your city?",
        'moon.faq.da1': 'The site shows the current moon phase and illumination percentage live. The moon goes through eight phases over a 29.5-day cycle.',
        'moon.faq.dq2': 'When is the next full moon?',
        'moon.faq.da2': 'A full moon occurs every 29.5 days. The site displays the Gregorian and Hijri date of the next full moon at 100% illumination.',
        'moon.faq.dq3': 'When is the next new moon?',
        'moon.faq.da3': 'A new moon is the instant the Moon lies between Earth and the Sun at 0% illumination. It repeats every 29.5 days and marks the start of a new lunar month.',
        'moon.faq.dq4': 'How many days until the next full moon?',
        'moon.faq.da4': 'The site automatically computes the days remaining until the next full moon based on the current astronomical position of the Moon.',
        'moon.faq.dq5': "What is the moon's age today?",
        'moon.faq.da5': 'Moon age is the number of days elapsed since the last new moon. It ranges from 0 to 29.5 days.',
        'moon.faq.dq6': 'What time does the moon rise tonight in your city?',
        'moon.faq.da6': 'Moonrise depends on your longitude. The site shows moonrise time in local timezone once your location is detected.',
        'moon.faq.dq7': 'What time does the moon set tonight in your city?',
        'moon.faq.da7': 'Moonset depends on your longitude and latitude. The site shows moonset time in local timezone.',
        'moon.faq.dq8': 'What is the distance between your city and the Moon right now?',
        'moon.faq.da8': 'The Earth–Moon distance ranges between 356,500 km (perigee) and 406,700 km (apogee). The site computes the exact topocentric distance from your city to the Moon.',
        // ===== FAQ General (new general astronomy/Islamic questions) =====
        'moon.faq.q15': 'What is a lunar eclipse and why does it happen?',
        'moon.faq.a15': 'A lunar eclipse occurs when Earth is positioned between the Sun and Moon, so the Moon enters Earth\'s shadow. It only happens during a full moon, and ranges from partial to total. During a total eclipse the Moon turns dark red — the "blood moon" — caused by sunlight scattering through Earth\'s atmosphere.',
        'moon.faq.q16': 'Why do we always see the same face of the Moon?',
        'moon.faq.a16': 'This is called "tidal locking": the Moon\'s rotation period (27.3 days) equals its orbital period around Earth. As a result the same hemisphere always faces Earth, while the opposite side is called the "far side" and was first photographed in 1959 by Soviet probe Luna 3.',
        'moon.faq.q17': 'How does the Moon affect tides?',
        'moon.faq.a17': 'Moon gravity pulls ocean water, causing a bulge on the Moon-facing side (high tide) and another on the opposite side due to inertia. Between them are low tides. Roughly two highs and two lows occur daily. When Moon aligns with the Sun (new or full moon), tides reach maximum — "spring tides".',
        'moon.faq.q18': 'Do lunar phases affect sleep and mood?',
        'moon.faq.a18': 'Limited scientific studies suggest some people experience sleep about 20–30 minutes shorter during full moon nights, possibly due to increased sky brightness. The effect is small and varies between individuals; there is no conclusive evidence that the Moon affects mood or behavior generally.',
        'moon.faq.q19': 'Why does the Moon sometimes look yellow or red?',
        'moon.faq.a19': "When the Moon is near the horizon, its light passes through a thicker slice of atmosphere. Blue wavelengths scatter away, leaving red and yellow to reach the eye. This is the same effect that colors sunrise and sunset. Once high in the sky the Moon returns to its silvery-white color.",
        'moon.faq.q20': 'What are a "Blue Moon" and "Supermoon"?',
        'moon.faq.a20': 'Blue Moon: the second full moon in the same Gregorian month; occurs about every 2.7 years (it is not actually blue). Supermoon: a full moon coinciding with the Moon\'s closest point to Earth (perigee), making it appear ~14% larger and ~30% brighter than an average full moon.',
        // ===== Dynamic answer templates (placeholders: {city} {phaseIcon} {phaseName} {illum} {age} {date} {hijri} {days} {time} {distance}) =====
        'moon.faq.tpl_dq1': '{phaseIcon} {phaseName} — at {illum}% illumination. This is the current moon phase in {city} right now.',
