        'ramadan.faq_q3': 'What is the Hijri date of Ramadan\u2019s start?',
        'ramadan.faq_a3': 'It falls on the 1st of Ramadan {hyear} AH.',
        'ramadan.faq_q4': 'Can Ramadan\u2019s start date vary between countries?',
        'ramadan.faq_a4': 'Yes, it may differ by one day between countries based on local crescent sighting and the approved religious authority.',
        'ramadan.faq_q5': 'How is the start of Ramadan determined?',
        'ramadan.faq_a5': 'By sighting the Ramadan crescent after sunset on the 29th of Shaban, or by completing Shaban as 30 days.',
        'ramadan.faq_q6': 'How is Ramadan related to the crescent sighting?',
        'ramadan.faq_a6': 'Ramadan\u2019s start and end are religiously tied to crescent sighting, which sometimes differs from the astronomical calculation by one day.',
        'ramadan.faq_q7': 'Is the shown date final or estimated?',
        'ramadan.faq_a7': 'The date shown is an astronomical estimate; the official final announcement is issued by the religious authority in each country.',
        'ramadan.faq_q8': 'When is the Ramadan crescent usually observed?',
        'ramadan.faq_a8': 'Usually, the crescent is observed after sunset on the 29th of Shaban across various regions of the Muslim world.',
        'ramadan.faq_q9': 'Does Ramadan start immediately after the new moon?',
        'ramadan.faq_a9': 'No, Ramadan starts when the crescent is sighted about 15–30 hours after the new moon, not at the moment of the new moon itself.',
        'ramadan.faq_q10': 'Why does Ramadan shift every Gregorian year?',
        'ramadan.faq_a10': 'Because the Hijri lunar year is about 10–11 days shorter than the Gregorian solar year, so Ramadan advances by that amount annually.',
        'ramadan.info_title': '📖 About the Month of Ramadan',
        'ramadan.info_h1': 'What is Ramadan?',
        'ramadan.info_h1_body': 'Ramadan is the 9th month of the Hijri lunar calendar and one of the most important months in Islam. The Quran was revealed in it, and Muslims fast from dawn to sunset throughout its days.',
        'ramadan.info_h2': 'How is the start of Ramadan determined?',
        'ramadan.info_h2_body': 'It is determined by sighting the crescent after sunset on the 29th of Shaban. If not sighted, Shaban is completed as 30 days and Ramadan begins the following day.',
        'ramadan.info_h3': 'Why does Ramadan shift each Gregorian year?',
        'ramadan.info_h3_body': 'The Hijri lunar year is about 10–11 days shorter than the Gregorian solar year, so Ramadan (along with every Islamic occasion) advances by the same amount annually in the Gregorian calendar.',
