        'eid_fitr.faq_q9': 'What are the main rites of Eid al-Fitr?',
        'eid_fitr.faq_a9': 'Eid prayer, paying Zakat al-Fitr before prayer, takbir, visiting relatives, and exchanging greetings among Muslims.',
        'eid_fitr.faq_q10': 'Why does Eid al-Fitr change each Gregorian year?',
        'eid_fitr.faq_a10': 'Because the lunar Hijri year is about 10-11 days shorter than the Gregorian year, Eid advances by the same amount each year.',
        'eid_fitr.info_title': '📖 About Eid al-Fitr',
        'eid_fitr.info_h1': 'What is Eid al-Fitr',
        'eid_fitr.info_h1_body': 'Eid al-Fitr is one of the two Islamic Eids, coming after completing the fast of the blessed month of Ramadan, beginning on the first day of Shawwal. It includes takbir, Eid prayer, paying Zakat al-Fitr before prayer, and exchanging greetings.',
        'eid_fitr.info_h2': 'How is Eid al-Fitr established',
        'eid_fitr.info_h2_body': 'Eid al-Fitr is established by one of two ways: sighting the Shawwal crescent after sunset on the 29th day of Ramadan, or completing Ramadan as 30 days if the crescent is not seen.',
        'eid_fitr.info_h3': 'Why does Eid al-Fitr advance each Gregorian year',
        'eid_fitr.info_h3_body': 'The lunar Hijri year is about 10-11 days shorter than the Gregorian year, so Eid al-Fitr advances the same amount each year in the Gregorian calendar, cycling through all seasons every ~33 years.',
