        'eid_adha.faq_q5': 'What is the link between Eid al-Adha and Hajj?',
        'eid_adha.faq_a5': 'Eid al-Adha is the Day of Sacrifice following the Day of Arafah. It falls on the 10th of Dhul-Hijjah, the day pilgrims offer their sacrifices in Mina.',
        'eid_adha.faq_q6': 'What is Udhiyah and what is its ruling?',
        'eid_adha.faq_a6': 'Udhiyah is the animal sacrificed to Allah during the Eid days. It is a confirmed Sunnah (mu’akkadah) for those able, according to the majority of scholars.',
        'eid_adha.faq_q7': 'How many days does Eid al-Adha last?',
        'eid_adha.faq_a7': 'Eid lasts four days: the Day of Sacrifice (10 Dhul-Hijjah) and the three Days of Tashreeq (11, 12, and 13 Dhul-Hijjah).',
        'eid_adha.faq_q8': 'What is the virtue of the Day of Arafah?',
        'eid_adha.faq_a8': 'The Day of Arafah is 9 Dhul-Hijjah, when pilgrims stand at Mount Arafat. Fasting it for non-pilgrims expiates the sins of two years.',
        'eid_adha.faq_q9': 'What are the main rites of Eid al-Adha?',
        'eid_adha.faq_a9': 'Eid prayer, takbir, performing the Udhiyah (sacrifice), exchanging greetings, and visiting relatives.',
        'eid_adha.faq_q10': 'Why does Eid al-Adha change each Gregorian year?',
        'eid_adha.faq_a10': 'Because the lunar Hijri year is about 10–11 days shorter than the Gregorian year, Eid advances by the same amount each year.',
        'eid_adha.info_title': '📖 About Eid al-Adha',
        'eid_adha.info_h1': 'What is Eid al-Adha',
