        'eid_adha.info_h2': 'How is Eid al-Adha established',
        'eid_adha.info_h2_body': 'Eid al-Adha is established by confirming the start of Dhul-Hijjah through sighting its crescent, then counting to the 10th day. The date may differ by one day between countries depending on sighting.',
        'eid_adha.info_h3': 'Why does Eid al-Adha advance each Gregorian year',
