        'hijri_ny.intro': 'Discover the days remaining until the new Hijri (Islamic lunar) year with the expected Gregorian and Hijri dates. The new year begins on 1 Muharram, and the announcement may differ by a day between countries based on the Muharram crescent sighting.',
        'hijri_ny.event_name': 'Hijri New Year',
        'hijri_ny.hijri_1': '1 Muharram',
        'hijri_ny.meta_title': '📅 Hijri New Year Countdown — Expected Date & Live Timer',
        'hijri_ny.meta_desc': 'Accurate countdown to the new Hijri year (1 Muharram) — in days, hours, and minutes — with Gregorian and Hijri dates and historical context of the Prophetic migration (Hijrah).',
        'hijri_ny.cards_title': '📋 Key Information',
