        'moon.intro_date_template': 'In {city}, on {date}, the Moon is in a {phaseIcon} {phaseName} phase with an illumination of {illum}%, and its age is {age} days since the last new moon. It is currently located in the {zodiacIcon} {zodiacName} constellation based on its position along the ecliptic (the apparent path of the Sun). These figures are computed using high-precision astronomical algorithms following Jean Meeus\u2019 methodologies, while the constellation is determined based on the Moon\u2019s position within the officially recognized constellation boundaries.',
