        'eid_adha.faq_title': '❓ Questions fréquentes sur l’Aïd el-Adha',
        'eid_adha.faq_q1': 'Combien de jours avant l’Aïd el-Adha ?',
        'eid_adha.faq_a1': 'Il reste {n} jours avant l’Aïd el-Adha prévu.',
        'eid_adha.faq_q2': 'Quand a lieu l’Aïd el-Adha cette année ?',
        'eid_adha.faq_a2': 'L’Aïd el-Adha {hyear} H tombe le {date} selon les estimations.',
        'eid_adha.faq_q3': 'Quelle est la date hégirienne de l’Aïd el-Adha ?',
        'eid_adha.faq_a3': 'Elle correspond au 10e jour de Dhou al-Hijjah {hyear} H.',
        'eid_adha.faq_q4': 'La date de l’Aïd el-Adha peut-elle différer selon les pays ?',
        'eid_adha.faq_a4': 'Oui, elle peut varier d’un jour selon l’observation locale du croissant de Dhou al-Hijjah.',
        'eid_adha.faq_q5': 'Quel est le lien entre l’Aïd el-Adha et le Hadj ?',
        'eid_adha.faq_a5': 'L’Aïd el-Adha est le jour du sacrifice qui suit le jour d’Arafat. Il tombe le 10 Dhou al-Hijjah, jour où les pèlerins offrent leurs sacrifices à Mina.',
        'eid_adha.faq_q6': 'Qu’est-ce que la Udhiyah et quel est son statut ?',
        'eid_adha.faq_a6': 'La Udhiyah est l’animal sacrifié à Allah pendant l’Aïd. C’est une sunnah confirmée pour ceux qui en ont la capacité selon la majorité des savants.',
        'eid_adha.faq_q7': 'Combien de temps dure l’Aïd el-Adha ?',
        'eid_adha.faq_a7': 'L’Aïd dure quatre jours : le jour du sacrifice (10 Dhou al-Hijjah) et les trois jours de Tashreeq (11, 12, 13 Dhou al-Hijjah).',
        'eid_adha.faq_q8': 'Quelle est la vertu du jour d’Arafat ?',
        'eid_adha.faq_a8': 'Le jour d’Arafat est le 9 Dhou al-Hijjah, jour de la station à Arafat. Pour les non-pèlerins, son jeûne expie les péchés de deux ans.',
        'eid_adha.faq_q9': 'Quels sont les principaux rites de l’Aïd el-Adha ?',
        'eid_adha.faq_a9': 'Prière de l’Aïd, takbir, accomplissement de la Udhiyah (sacrifice), échange de vœux et visites familiales.',
        'eid_adha.faq_q10': 'Pourquoi la date de l’Aïd el-Adha change-t-elle chaque année grégorienne ?',
        'eid_adha.faq_a10': 'Parce que l’année hégirienne lunaire est environ 10-11 jours plus courte, l’Aïd avance du même nombre chaque année.',
        'eid_adha.info_title': '📖 À propos de l’Aïd el-Adha',
        'eid_adha.info_h1': 'Qu’est-ce que l’Aïd el-Adha',
        'eid_adha.info_h1_body': 'L’Aïd el-Adha est la plus grande des deux fêtes islamiques, tombant le 10 Dhou al-Hijjah après le jour d’Arafat. Connu comme le jour du sacrifice, les musulmans offrent des sacrifices d’animaux en souvenir de la sunnah du Prophète Ibrahim (paix sur lui).',
        'eid_adha.info_h2': 'Comment l’Aïd el-Adha est-il établi',
        'eid_adha.info_h2_body': 'L’Aïd el-Adha est établi par la confirmation du début de Dhou al-Hijjah via l’observation du croissant, puis en comptant le 10e jour. La date peut varier d’un jour selon les pays.',
        'eid_adha.info_h3': 'Pourquoi l’Aïd el-Adha avance-t-il chaque année grégorienne',
        'eid_adha.info_h3_body': 'L’année hégirienne lunaire est environ 10-11 jours plus courte que l’année grégorienne, donc l’Aïd el-Adha avance du même nombre chaque année, parcourant toutes les saisons en ~33 ans.',
        'eid_adha.links_title': '🔗 Liens connexes',
