        // ─── hijri_ny (fr) ───
        'hijri_ny.h1': '📅 Combien de jours avant le Nouvel An hégirien ?',
        'hijri_ny.intro': 'Découvrez les jours restants avant le nouvel an hégirien (calendrier lunaire islamique) avec les dates grégorienne et hégirienne prévues. La nouvelle année commence le 1er Mouharram, et l’annonce peut varier d’un jour selon l’observation du croissant de Mouharram dans chaque pays.',
        'hijri_ny.event_name': 'Nouvel An hégirien',
        'hijri_ny.hijri_1': '1 Mouharram',
        'hijri_ny.meta_title': '📅 Combien de jours avant le Nouvel An hégirien ? — Date prévue et compte à rebours',
        'hijri_ny.meta_desc': 'Compte à rebours précis jusqu’au nouvel an hégirien (1 Mouharram) — en jours, heures et minutes — avec les dates grégorienne et hégirienne et le contexte historique de l’Hégire prophétique.',
        'hijri_ny.cards_title': '📋 Informations clés',
        'hijri_ny.card1_title': 'Nouvel An hégirien prévu',
        'hijri_ny.card2_title': 'Date hégirienne',
