        'hijri_ny.card4_title': 'Statut',
        'hijri_ny.card4_value': 'Calculé · En attente d’observation',
        'hijri_ny.notice_title': '📜 Vérification de la date',
        'hijri_ny.notice_body': 'Le Nouvel An hégirien commence le premier jour de Mouharram. La date affichée est calculée astronomiquement selon le calendrier hégirien tabulaire ; l’annonce officielle peut varier d’un jour selon l’observation locale du croissant de Mouharram dans chaque pays.',
        'hijri_ny.lunar_title': '🌙 Lien lunaire',
        'hijri_ny.lunar_current': 'Phase actuelle de la lune :',
        'hijri_ny.lunar_link_today': '🌙 État de la lune aujourd’hui →',
