        'hijri_ny.lunar_link_crescent': '🌒 Prochain croissant de Mouharram →',
        'hijri_ny.years_title': '📅 Dates du Nouvel An hégirien pour les prochaines années',
        'hijri_ny.years_col_hijri': 'Année hégirienne',
        'hijri_ny.years_col_greg': 'Année grégorienne',
        'hijri_ny.years_col_start': '1 Mouharram (estimation)',
