        'moon.intro_date_template': 'À {city}, le {date}, la Lune est en phase {phaseIcon} {phaseName} avec une illumination de {illum} %, et son âge est de {age} jours depuis la dernière nouvelle lune. Elle se trouve actuellement dans la constellation {zodiacIcon} {zodiacName} selon sa position sur l\u2019écliptique (la trajectoire apparente du Soleil). Ces données sont calculées à l\u2019aide d\u2019algorithmes astronomiques de haute précision suivant les méthodologies de Jean Meeus, tandis que la constellation est déterminée selon la position de la Lune dans les limites de constellations officiellement reconnues.',
