        'moon.insight.new.visual': 'La Lune n\u2019est pas visible ce soir — elle se trouve entre la Terre et le Soleil, sa face tournée vers nous étant dans l\u2019ombre.',
        'moon.insight.new.visibility': 'La Lune n\u2019est pas observable durant la nouvelle lune, même au télescope ; elle réapparaîtra comme un fin croissant à l\u2019ouest un ou deux jours plus tard.',
        'moon.insight.new.about': 'La nouvelle lune marque le début du mois lunaire : le moment où la Lune se place entre la Terre et le Soleil, laissant sa face proche sans lumière.',
        'moon.insight.waxing_crescent.visual': 'La Lune apparaît comme un fin croissant bas à l\u2019ouest, juste après le coucher du soleil.',
        'moon.insight.waxing_crescent.visibility': 'Visible brièvement (~1 à 2 heures) avant de se coucher, et nécessite un horizon dégagé.',
        'moon.insight.waxing_crescent.about': 'Le premier croissant est la première phase après la nouvelle lune : une mince portion éclairée commence à croître jour après jour.',
        'moon.insight.first_quarter.visual': 'La Lune se montre sous la forme d\u2019un demi-disque lumineux, se levant l\u2019après-midi et restant jusque vers minuit.',
        'moon.insight.first_quarter.visibility': 'Bien visible pendant la majeure partie de la soirée, du coucher du soleil jusque vers minuit.',
        'moon.insight.first_quarter.about': 'Le premier quartier est le point à mi-chemin entre la nouvelle lune et la pleine lune, avec environ 50% d\u2019illumination.',
        'moon.insight.waxing_gibbous.visual': 'La Lune apparaît gibbeuse et brillante, dominant la plus grande partie du ciel nocturne.',
        'moon.insight.waxing_gibbous.visibility': 'Facilement visible pendant la majeure partie de la nuit, parfois même de jour avant le coucher du soleil.',
        'moon.insight.waxing_gibbous.about': 'La Lune gibbeuse croissante est la phase entre le premier quartier et la pleine lune, avec une illumination de 51% à 99%.',
        'moon.insight.full.visual': 'La Lune apparaît comme un disque pleinement illuminé, opposé au Soleil dans le ciel.',
        'moon.insight.full.visibility': 'Facilement visible toute la nuit, du lever de lune au coucher de soleil jusqu\u2019au coucher de lune au lever de soleil — la phase la plus brillante.',
        'moon.insight.full.about': 'La pleine lune correspond à 100% d\u2019illumination : la Terre se trouve entre la Lune et le Soleil.',
        'moon.insight.waning_gibbous.visual': 'La Lune apparaît gibbeuse et lumineuse, se levant après minuit et montant haut à l\u2019aube.',
        'moon.insight.waning_gibbous.visibility': 'Visible de minuit jusqu\u2019après le lever du soleil, souvent encore observable le matin.',
        'moon.insight.waning_gibbous.about': 'La Lune gibbeuse décroissante est la phase juste après la pleine lune, avec une illumination décroissante de 99% à 51%.',
        'moon.insight.last_quarter.visual': 'La Lune se présente en demi-disque — cette fois c\u2019est la moitié gauche qui est éclairée.',
