        'eid_fitr.faq_q5': 'Ramazan Bayramı nasıl belirlenir?',
        'eid_fitr.faq_a5': 'Ramazan’ın 29. gününün gün batımından sonra Şevval hilalinin görülmesiyle veya Ramazan’ın 30 güne tamamlanmasıyla.',
        'eid_fitr.faq_q6': 'Ramazan Bayramı ile Şevval hilali arasındaki bağlantı nedir?',
        'eid_fitr.faq_a6': 'Ramazan Bayramı, hilalin görülmesiyle belirlenen Şevval’ın başlamasıyla başlar, bu nedenle astronomik hesaplamadan bir gün farklı olabilir.',
        'eid_fitr.faq_q7': 'Gösterilen tarih kesin mi yoksa tahmini mi?',
        'eid_fitr.faq_a7': 'Astronomik bir tahmindir; nihai resmi ilan her ülkenin dini makamından gelir.',
