        'hijri_ny.h1': '📅 Hicri Yılbaşına Ne Kadar Kaldı?',
        'hijri_ny.intro': 'Yeni hicri (İslami ay) yılına kalan günleri miladi ve hicri tarihlerle birlikte keşfedin. Yeni yıl 1 Muharrem’de başlar; resmî ilan, her ülkedeki Muharrem hilalinin görülmesine göre bir gün farklılık gösterebilir.',
        'hijri_ny.event_name': 'Hicri Yılbaşı',
        'hijri_ny.hijri_1': '1 Muharrem',
        'hijri_ny.meta_title': '📅 Hicri Yılbaşı Geri Sayım — Beklenen Tarih ve Canlı Sayaç',
        'hijri_ny.meta_desc': 'Yeni hicri yıla (1 Muharrem) gün, saat ve dakika cinsinden hassas geri sayım — miladi ve hicri tarihler ile peygamber efendimizin hicretinin tarihsel bağlamıyla birlikte.',
        'hijri_ny.cards_title': '📋 Temel Bilgiler',
