        'hijri_ny.notice_body': 'Hicri Yılbaşı, Muharrem ayının ilk günü başlar. Gösterilen tarih tablo esaslı hicri takvime göre astronomik olarak hesaplanır; resmi ilan, her ülkedeki Muharrem hilalinin yerel olarak görülmesine bağlı olarak bir gün değişebilir.',
