        'hijri_ny.cities_title': '🌍 Dünyada Hicri Yılbaşı',
        'hijri_ny.city_sa': 'Suudi Arabistan’da Hicri Yılbaşı',
        'hijri_ny.city_eg': 'Mısır’da Hicri Yılbaşı',
        'hijri_ny.city_ae': 'BAE’de Hicri Yılbaşı',
