        'ramadan.info_h2_body': 'Der Beginn des Ramadan wird durch die Sichtung der Mondsichel nach Sonnenuntergang am 29. Tag des Schaaban bestätigt. Wird die Mondsichel nicht gesehen, wird Schaaban mit 30 Tagen vollendet, und Ramadan beginnt am folgenden Tag.',
        'ramadan.info_h3': 'Warum verschiebt sich Ramadan jedes gregorianische Jahr',
        'ramadan.info_h3_body': 'Das Hidschri-Mondjahr ist etwa 10-11 Tage kürzer als das gregorianische Sonnenjahr. Daher verschiebt sich Ramadan (und alle islamischen Anlässe) jedes Jahr um denselben Betrag im gregorianischen Kalender nach vorne.',
