        'eid_fitr.faq_q4': 'Kann das Eid-al-Fitr-Datum zwischen Ländern variieren?',
        'eid_fitr.faq_a4': 'Ja, es kann je nach lokaler Sichtung der Schawwal-Mondsichel um einen Tag abweichen.',
        'eid_fitr.faq_q5': 'Wie wird Eid al-Fitr festgelegt?',
        'eid_fitr.faq_a5': 'Durch die Sichtung der Schawwal-Mondsichel nach Sonnenuntergang am 29. Tag Ramadan oder durch die Vollendung des Ramadan mit 30 Tagen.',
        'eid_fitr.faq_q6': 'Wie hängt Eid al-Fitr mit der Schawwal-Mondsichel zusammen?',
        'eid_fitr.faq_a6': 'Eid al-Fitr beginnt mit dem Beginn des Schawwal, der durch die Sichtung der Mondsichel festgelegt wird, daher kann es um einen Tag von der astronomischen Berechnung abweichen.',
        'eid_fitr.faq_q7': 'Ist das angezeigte Datum endgültig oder erwartet?',
        'eid_fitr.faq_a7': 'Es ist eine astronomische Schätzung; die endgültige offizielle Ankündigung erfolgt durch die religiöse Behörde jedes Landes.',
        'eid_fitr.faq_q8': 'Wie lange dauert Eid al-Fitr?',
        'eid_fitr.faq_a8': 'Der erste Tag ist 1. Schawwal, und das Fest dauert in den meisten muslimischen Ländern 3 Tage.',
        'eid_fitr.faq_q9': 'Was sind die wichtigsten Riten von Eid al-Fitr?',
        'eid_fitr.faq_a9': 'Eid-Gebet, Zahlung der Zakat al-Fitr vor dem Gebet, Takbir, Familienbesuche und Glückwunschaustausch.',
        'eid_fitr.faq_q10': 'Warum ändert sich das Eid-al-Fitr-Datum jedes gregorianische Jahr?',
        'eid_fitr.faq_a10': 'Weil das Hidschri-Mondjahr etwa 10-11 Tage kürzer ist, verschiebt sich Eid jedes Jahr um denselben Betrag.',
        'eid_fitr.info_title': '📖 Über Eid al-Fitr',
        'eid_fitr.info_h1': 'Was ist Eid al-Fitr',
        'eid_fitr.info_h1_body': 'Eid al-Fitr ist eines der zwei islamischen Feste und folgt auf das Fasten im gesegneten Ramadan, beginnend am 1. Schawwal. Es umfasst Takbir, Eid-Gebet, Zakat al-Fitr vor dem Gebet und den Austausch von Glückwünschen.',
        'eid_fitr.info_h2': 'Wie wird Eid al-Fitr festgelegt',
        'eid_fitr.info_h2_body': 'Eid al-Fitr wird auf zwei Wegen festgelegt: durch die Sichtung der Schawwal-Mondsichel nach Sonnenuntergang am 29. Tag Ramadan oder durch die Vollendung des Ramadan mit 30 Tagen, wenn die Mondsichel nicht gesehen wird.',
        'eid_fitr.info_h3': 'Warum verschiebt sich Eid al-Fitr jedes gregorianische Jahr',
        'eid_fitr.info_h3_body': 'Das Hidschri-Mondjahr ist etwa 10-11 Tage kürzer als das gregorianische Jahr, daher verschiebt sich Eid al-Fitr jedes Jahr um denselben Betrag und durchläuft alle Jahreszeiten in etwa 33 Jahren.',
        'eid_fitr.links_title': '🔗 Verwandte Links',
