        'eid_adha.h1': '🐑 Wie lange noch bis Eid al-Adha?',
        'eid_adha.intro': 'Entdecken Sie die verbleibenden Tage bis zum gesegneten Eid al-Adha mit dem erwarteten gregorianischen und Hidschri-Datum. Eid al-Adha fällt auf den Tag des Opfers (10. Dhul-Hidscha) und kann je nach Dhul-Hidscha-Mondsichtung um einen Tag abweichen.',
        'eid_adha.event_name': 'Eid al-Adha',
