        'eid_adha.meta_desc': 'Präziser Countdown bis zum gesegneten Eid al-Adha (Opferfest) — in Tagen, Stunden und Minuten — mit gregorianischem und Hidschri-Datum.',
        'eid_adha.cards_title': '📋 Wichtige Informationen',
