        'eid_adha.notice_title': '📜 Datumsbestätigung',
        'eid_adha.notice_body': 'Eid al-Adha ist an den Opfertag gebunden, den 10. Dhul-Hidscha, nach dem Tag von Arafat. Das angezeigte Datum wird astronomisch berechnet und kann um einen Tag von der offiziellen Ankündigung abweichen.',
