        'eid_adha.faq_title': '❓ Häufige Fragen zu Eid al-Adha',
        'eid_adha.faq_q1': 'Wie lange noch bis Eid al-Adha?',
        'eid_adha.faq_a1': 'Bis zum erwarteten Eid al-Adha sind es noch {n} Tage.',
        'eid_adha.faq_q2': 'Wann ist Eid al-Adha in diesem Jahr?',
        'eid_adha.faq_a2': 'Eid al-Adha {hyear} H fällt voraussichtlich auf {date}.',
        'eid_adha.faq_q3': 'Was ist das Hidschri-Datum von Eid al-Adha?',
        'eid_adha.faq_a3': 'Es entspricht dem 10. Tag des Dhul-Hidscha {hyear} H.',
        'eid_adha.faq_q4': 'Kann das Eid-al-Adha-Datum zwischen Ländern variieren?',
        'eid_adha.faq_a4': 'Ja, es kann je nach lokaler Sichtung der Dhul-Hidscha-Mondsichel um einen Tag abweichen.',
        'eid_adha.faq_q5': 'Wie hängt Eid al-Adha mit dem Hadsch zusammen?',
        'eid_adha.faq_a5': 'Eid al-Adha ist der Opfertag nach dem Tag von Arafat. Er fällt auf den 10. Dhul-Hidscha, den Tag, an dem Pilger ihre Opfer in Mina darbringen.',
        'eid_adha.faq_q6': 'Was ist Udhiyah und welches Urteil gilt dafür?',
        'eid_adha.faq_a6': 'Udhiyah ist das Tieropfer an Allah während der Eid-Tage. Laut der Mehrheit der Gelehrten ist es eine bestätigte Sunnah für diejenigen, die es sich leisten können.',
        'eid_adha.faq_q7': 'Wie lange dauert Eid al-Adha?',
        'eid_adha.faq_a7': 'Eid dauert vier Tage: den Opfertag (10. Dhul-Hidscha) und die drei Tage von Taschreeq (11., 12. und 13. Dhul-Hidscha).',
        'eid_adha.faq_q8': 'Was ist die Tugend des Tages von Arafat?',
        'eid_adha.faq_a8': 'Der Tag von Arafat ist der 9. Dhul-Hidscha, an dem Pilger auf dem Berg Arafat stehen. Fasten an diesem Tag sühnt für Nicht-Pilger die Sünden von zwei Jahren.',
        'eid_adha.faq_q9': 'Was sind die wichtigsten Riten von Eid al-Adha?',
        'eid_adha.faq_a9': 'Eid-Gebet, Takbir, Durchführung der Udhiyah (Opferung), Austausch von Glückwünschen und Familienbesuche.',
        'eid_adha.faq_q10': 'Warum ändert sich das Eid-al-Adha-Datum jedes gregorianische Jahr?',
        'eid_adha.faq_a10': 'Weil das Hidschri-Mondjahr etwa 10–11 Tage kürzer ist, verschiebt sich Eid jedes Jahr um denselben Betrag.',
        'eid_adha.info_title': '📖 Über Eid al-Adha',
        'eid_adha.info_h1': 'Was ist Eid al-Adha',
        'eid_adha.info_h1_body': 'Eid al-Adha ist das größere der beiden islamischen Feste und fällt auf den 10. Dhul-Hidscha nach dem Tag von Arafat. Es ist als Opfertag bekannt, an dem Muslime Tiere opfern, um die Sunnah von Prophet Ibrahim (Friede sei mit ihm) zu ehren.',
        'eid_adha.info_h2': 'Wie wird Eid al-Adha festgelegt',
        'eid_adha.info_h2_body': 'Eid al-Adha wird durch die Bestätigung des Dhul-Hidscha-Beginns durch die Sichtung seiner Mondsichel festgelegt, dann zählt man bis zum 10. Tag. Das Datum kann zwischen Ländern um einen Tag abweichen.',
        'eid_adha.info_h3': 'Warum verschiebt sich Eid al-Adha jedes gregorianische Jahr',
        'eid_adha.info_h3_body': 'Das Hidschri-Mondjahr ist etwa 10–11 Tage kürzer als das gregorianische Jahr, daher verschiebt sich Eid al-Adha jedes Jahr um denselben Betrag und durchläuft alle Jahreszeiten in etwa 33 Jahren.',
        'eid_adha.links_title': '🔗 Verwandte Links',
