        'ramadan.faq_q1': '¿Cuánto falta para el Ramadán?',
        'ramadan.faq_a1': 'Faltan {n} días para el inicio previsto del Ramadán.',
        'ramadan.faq_q2': '¿Cuándo comienza el Ramadán este año?',
        'ramadan.faq_a2': 'El Ramadán {hyear} H comienza el {date} según estimaciones.',
        'ramadan.faq_q3': '¿Cuál es la fecha hégira del inicio del Ramadán?',
        'ramadan.faq_a3': 'Corresponde al primer día del mes de Ramadán {hyear} H.',
        'ramadan.faq_q4': '¿Puede variar la fecha del Ramadán entre países?',
        'ramadan.faq_a4': 'Sí, puede variar un día según el avistamiento local del creciente y la autoridad religiosa de cada país.',
        'ramadan.faq_q5': '¿Cómo se determina el inicio del Ramadán?',
        'ramadan.faq_a5': 'Por el avistamiento del creciente del Ramadán tras la puesta del sol del 29 de Sha\u2019ban, o completando Sha\u2019ban con 30 días.',
        'ramadan.faq_q6': '¿Cuál es la relación del Ramadán con el avistamiento del creciente?',
        'ramadan.faq_a6': 'El inicio y el fin del Ramadán están ligados religiosamente al avistamiento del creciente, lo que puede diferir un día del cálculo astronómico.',
        'ramadan.faq_q7': '¿Es la fecha mostrada definitiva o prevista?',
        'ramadan.faq_a7': 'La fecha mostrada es una estimación astronómica; el anuncio oficial definitivo lo emite la autoridad religiosa de cada país.',
        'ramadan.faq_q8': '¿Cuándo se observa habitualmente el creciente del Ramadán?',
        'ramadan.faq_a8': 'El creciente suele observarse tras la puesta del sol del 29 de Sha\u2019ban en varias regiones del mundo musulmán.',
        'ramadan.faq_q9': '¿Comienza el Ramadán justo después de la luna nueva?',
        'ramadan.faq_a9': 'No, el Ramadán comienza cuando el creciente se hace visible unas 15-30 horas después de la luna nueva, no en el momento de la luna nueva misma.',
        'ramadan.faq_q10': '¿Por qué cambia la fecha del Ramadán cada año gregoriano?',
        'ramadan.faq_a10': 'Porque el año hégira lunar es unos 10-11 días más corto que el año gregoriano, el Ramadán se adelanta la misma cantidad cada año.',
        'ramadan.info_title': '📖 Sobre el mes de Ramadán',
        'ramadan.info_h1': 'Qué es el Ramadán',
        'ramadan.info_h1_body': 'El Ramadán es el noveno mes del calendario hégira lunar y uno de los meses más importantes del islam. En él fue revelado el Corán, y los musulmanes ayunan desde el alba hasta la puesta del sol durante todo el mes.',
        'ramadan.info_h2': 'Cómo se confirma el inicio del Ramadán',
        'ramadan.info_h2_body': 'El inicio del Ramadán se confirma con el avistamiento del creciente tras la puesta del sol del 29 de Sha\u2019ban. Si el creciente no se ve, Sha\u2019ban se completa con 30 días y el Ramadán comienza al día siguiente.',
        'ramadan.info_h3': 'Por qué el Ramadán se adelanta cada año gregoriano',
        'ramadan.info_h3_body': 'El año hégira lunar es unos 10-11 días más corto que el año gregoriano solar. Por eso el Ramadán (y todas las fiestas islámicas) se adelanta la misma cantidad cada año en el calendario gregoriano.',
