        'eid_fitr.faq_q8': '¿Cuánto dura el Eid al-Fitr?',
        'eid_fitr.faq_a8': 'El primer día del Eid es el 1 de Shawwal, y la fiesta dura 3 días en la mayoría de los países musulmanes.',
