        'eid_fitr.info_h1_body': 'El Eid al-Fitr es una de las dos fiestas islámicas, tras completar el ayuno del bendito Ramadán, empezando el 1 de Shawwal. Incluye takbir, oración del Eid, Zakat al-Fitr antes de la oración, y el intercambio de felicitaciones.',
        'eid_fitr.info_h2': 'Cómo se establece el Eid al-Fitr',
        'eid_fitr.info_h2_body': 'El Eid al-Fitr se establece por dos vías: el avistamiento del creciente de Shawwal tras la puesta del sol del 29 de Ramadán, o completando Ramadán con 30 días si el creciente no se ve.',
        'eid_fitr.info_h3': 'Por qué el Eid al-Fitr se adelanta cada año gregoriano',
        'eid_fitr.info_h3_body': 'El año hégira lunar es unos 10-11 días más corto que el año gregoriano, por eso el Eid al-Fitr se adelanta la misma cantidad cada año y recorre todas las estaciones cada ~33 años.',
