        'hijri_ny.lunar_link_crescent': '🌒 Próximo creciente de Muharram →',
        'hijri_ny.years_title': '📅 Fechas del Año Nuevo hégira en los próximos años',
        'hijri_ny.years_col_hijri': 'Año hégira',
        'hijri_ny.years_col_greg': 'Año gregoriano',
        'hijri_ny.years_col_start': '1 de Muharram (estimado)',
        'hijri_ny.years_col_note': 'Nota',
        'hijri_ny.years_note': '* Todas las fechas son estimaciones calculadas y pueden diferir en un día según el avistamiento.',
        'hijri_ny.years_note_cell': 'Estimado · Depende del avistamiento',
        'hijri_ny.cities_title': '🌍 El Año Nuevo hégira en el mundo',
        'hijri_ny.city_sa': 'Año Nuevo hégira en Arabia Saudita',
        'hijri_ny.city_eg': 'Año Nuevo hégira en Egipto',
        'hijri_ny.city_ae': 'Año Nuevo hégira en EAU',
