        'moon.desc_date_template': 'Fase de la Luna en {city} el {date}: iluminación, edad, salida y puesta lunar y constelación — calculadas con algoritmos astronómicos precisos.',
        'moon.intro_date_template': 'En {city}, el {date}, la Luna está en fase {phaseIcon} {phaseName} con una iluminación del {illum}%, y su edad es de {age} días desde la última luna nueva. Actualmente se encuentra en la constelación {zodiacIcon} {zodiacName} según su posición a lo largo de la eclíptica (la trayectoria aparente del Sol). Estos datos se calculan mediante algoritmos astronómicos de alta precisión siguiendo las metodologías de Jean Meeus, mientras que la constelación se determina según la posición de la Luna dentro de los límites de constelaciones reconocidos astronómicamente.',
