        'moon.insight.new.visual': 'La Luna no es visible esta noche — se sitúa entre la Tierra y el Sol, y su cara visible queda en sombra.',
        'moon.insight.new.visibility': 'La Luna no puede observarse durante la fase de luna nueva, ni siquiera con telescopio; reaparecerá como un fino creciente en el cielo occidental uno o dos días después.',
        'moon.insight.new.about': 'La luna nueva marca el inicio del mes lunar: el momento en que la Luna se sitúa entre la Tierra y el Sol, dejando su cara cercana sin iluminación.',
        'moon.insight.waxing_crescent.visual': 'La Luna aparece como un fino creciente bajo en el cielo occidental poco después del atardecer.',
        'moon.insight.waxing_crescent.visibility': 'Visible brevemente (~1–2 horas) antes de ocultarse; requiere un horizonte despejado.',
        'moon.insight.waxing_crescent.about': 'El creciente iluminante es la primera fase tras la luna nueva, cuando una pequeña porción iluminada empieza a crecer día a día.',
        'moon.insight.first_quarter.visual': 'La Luna se muestra como un medio disco brillante; sale por la tarde y permanece hasta alrededor de la medianoche.',
        'moon.insight.first_quarter.visibility': 'Fácilmente visible durante la mayor parte de la noche, desde el atardecer hasta la medianoche aproximadamente.',
        'moon.insight.first_quarter.about': 'El cuarto creciente es el punto medio entre la luna nueva y la luna llena, con aproximadamente un 50% de iluminación.',
        'moon.insight.waxing_gibbous.visual': 'La Luna aparece como una forma brillante y abultada que domina la mayor parte del cielo nocturno.',
        'moon.insight.waxing_gibbous.visibility': 'Fácilmente visible durante casi toda la noche; a veces puede verse incluso de día antes del atardecer.',
        'moon.insight.waxing_gibbous.about': 'La gibosa creciente es la fase entre el cuarto creciente y la luna llena, con una iluminación del 51% al 99%.',
        'moon.insight.full.visual': 'La Luna aparece como un disco completamente iluminado, opuesto al Sol en el cielo.',
        'moon.insight.full.visibility': 'Fácilmente visible durante toda la noche, desde el atardecer hasta el amanecer — es la fase más brillante.',
        'moon.insight.full.about': 'La luna llena se produce cuando la iluminación alcanza el 100% y la Tierra queda entre la Luna y el Sol.',
        'moon.insight.waning_gibbous.visual': 'La Luna aparece como una forma brillante y abultada; sale después de la medianoche y asciende al amanecer.',
        'moon.insight.waning_gibbous.visibility': 'Visible desde la medianoche hasta después del amanecer; a menudo aún puede verse por la mañana.',
        'moon.insight.waning_gibbous.about': 'La gibosa menguante es la fase inmediatamente posterior a la luna llena, con la iluminación bajando del 99% al 51%.',
        'moon.insight.last_quarter.visual': 'La Luna se muestra como medio disco — esta vez es la mitad izquierda la que está iluminada.',
        'moon.insight.last_quarter.visibility': 'Visible desde la medianoche hasta después del amanecer.',
        'moon.insight.last_quarter.about': 'El cuarto menguante es el punto medio entre la luna llena y la próxima luna nueva, con un 50% de iluminación aproximadamente.',
        'moon.insight.waning_crescent.visual': 'La Luna aparece como un fino creciente bajo en el cielo oriental justo antes del amanecer.',
        'moon.insight.waning_crescent.visibility': 'Visible brevemente antes del alba; requiere un horizonte oriental despejado.',
        'moon.insight.waning_crescent.about': 'El creciente menguante es la última fase antes de volver a la luna nueva — un fino creciente que se reduce día a día.',
