        'ramadan.faq_q4': 'রমজানের তারিখ কি দেশভেদে ভিন্ন হতে পারে?',
        'ramadan.faq_a4': 'হ্যাঁ, স্থানীয় চাঁদ দেখা এবং প্রতিটি দেশের অনুমোদিত ধর্মীয় কর্তৃপক্ষ অনুসারে এটি একদিন ভিন্ন হতে পারে।',
