        'ramadan.faq_a5': 'শা\u2019বানের ২৯তম দিনের সূর্যাস্তের পর রমজানের চাঁদ দেখে, অথবা শা\u2019বান ৩০ দিন পূর্ণ করে।',
        'ramadan.faq_q6': 'রমজানের সাথে চাঁদ দেখার সম্পর্ক কী?',
        'ramadan.faq_a6': 'রমজানের শুরু ও শেষ ফিকহিভাবে চাঁদ দেখার সাথে সংযুক্ত, তাই এটি কখনো কখনো জ্যোতির্বিদ্যাগত গণনা থেকে একদিন ভিন্ন হয়।',
        'ramadan.faq_q7': 'দেখানো তারিখ কি চূড়ান্ত নাকি অনুমানিত?',
        'ramadan.faq_a7': 'দেখানো তারিখটি জ্যোতির্বিদ্যাগত অনুমান; চূড়ান্ত আনুষ্ঠানিক ঘোষণা প্রতিটি দেশের ধর্মীয় কর্তৃপক্ষ থেকে আসে।',
        'ramadan.faq_q8': 'রমজানের হিলাল সাধারণত কখন দেখা যায়?',
        'ramadan.faq_a8': 'হিলাল সাধারণত ইসলামী বিশ্বের বিভিন্ন অঞ্চলে শা\u2019বানের ২৯তম দিনের সূর্যাস্তের পর অনুসন্ধান করা হয়।',
        'ramadan.faq_q9': 'রমজান কি অমাবস্যার পরপরই শুরু হয়?',
        'ramadan.faq_a9': 'না, রমজান শুরু হয় যখন অমাবস্যার প্রায় ১৫-৩০ ঘণ্টা পর হিলাল দৃশ্যমান হয়, অমাবস্যার মুহূর্তেই নয়।',
        'ramadan.faq_q10': 'প্রতিটি গ্রেগরিয়ান বছরে রমজানের তারিখ কেন পরিবর্তন হয়?',
        'ramadan.faq_a10': 'কারণ হিজরি চান্দ্র বছর গ্রেগরিয়ান বছরের চেয়ে প্রায় ১০-১১ দিন ছোট, তাই রমজান প্রতি বছর একই পরিমাণ এগিয়ে যায়।',
        'ramadan.info_title': '📖 রমজান মাস সম্পর্কে',
