        'hijri_ny.faq_a8': 'হিজরি নববর্ষ কোনো ধর্মীয় উৎসব নয় বরং আত্ম-মূল্যায়ন ও ইবরতের উপলক্ষ; তবে অনেক মুসলিম একে হিজরতের স্মরণের সুযোগ হিসেবে নেন।',
