        'hijri_ny.faq_a10': 'কারণ হিজরি বছর চান্দ্র এবং সৌর মিলাদি বছরের চেয়ে ছোট, তাই ইসলামী উপলক্ষ প্রতি মিলাদি বছরে 10–11 দিন এগিয়ে যায়।',
