        'ramadan.info_h2': 'Bagaimana permulaan Ramadan disahkan',
        'ramadan.info_h2_body': 'Permulaan Ramadan disahkan dengan rukyah hilal selepas matahari terbenam pada hari ke-29 Syaaban. Jika hilal tidak kelihatan, Syaaban disempurnakan kepada 30 hari, dan Ramadan bermula pada hari berikutnya.',
